      'kyc-data': { accounting: 'Ghi nhận khách hàng là ai và họ làm gì là thông tin. Góc nhìn kế toán ghi nhận các số dư như khoản nợ tiền gửi.' },
      'owes-liquidity': { accounting: 'Bút toán nợ phải trả ghi nhận số tiền. Rủi ro mà nó tạo ra, tức việc phải chi trả khi được yêu cầu, mới là rủi ro.' },
