  'cb-m02-seq-profit-waterfall-v2': {
    enTitle: 'The bank profitability waterfall',
    title: 'Thác lợi nhuận của ngân hàng',
    learningObjective: 'Sắp xếp các bước từ thu nhập hoạt động đến lợi nhuận ròng và các tỷ lệ sinh lời, và giải thích mỗi bước nuôi chỉ tiêu nào.',
    instructions: SEQUENCE_INSTRUCTIONS_VI,
    summary: 'Lợi nhuận là một dòng thác: khối lượng nằm ở trên cùng trong khi chi phí và tổn thất quyết định những gì còn lại. ROA và ROE sau đó quy kết quả đó theo tài sản và vốn chủ sở hữu.',
    sequenceEvidence: 'Dòng thác của chương trình bày phép tính theo thứ tự cố định: thu nhập lãi thuần và thu nhập ngoài lãi kết hợp thành tổng thu nhập hoạt động, chi phí hoạt động được trừ đi (cho ra lợi nhuận hoạt động trước dự phòng), dự phòng được trừ đi, thuế dẫn đến lợi nhuận ròng, rồi ROA và ROE quy kết quả đó theo tài sản và vốn chủ sở hữu. Mỗi bước làm việc trên kết quả của bước trước.',
    items: {
      'operating-income': 'Tổng thu nhập hoạt động: thu nhập lãi thuần cộng thu nhập ngoài lãi như phí',
      'subtract-opex': 'Trừ chi phí hoạt động: chi phí vận hành ngân hàng và phục vụ khách hàng',
      'subtract-provisions': 'Trừ dự phòng: khoản chi phí tín dụng',
      'tax-net-profit': 'Trừ thuế để ra lợi nhuận ròng',
      'scale-roa-roe': 'Quy lợi nhuận ròng theo tài sản và vốn chủ sở hữu thành ROA và ROE',
    },
    notes: {
      'operating-income': { explanation: 'Dòng thác bắt đầu bằng những gì ngân hàng kiếm được: chênh lệch ròng trên bảng cân đối cùng thu nhập phí và dịch vụ.', hint: 'Mọi khoản sau đây đều được trừ khỏi con số này.' },
      'subtract-opex': { explanation: 'Chi phí được khấu trừ khỏi thu nhập hoạt động, điều mà tỷ lệ chi phí trên thu nhập mô tả. Phần còn lại là lợi nhuận hoạt động trước dự phòng.', hint: 'Nó chỉ có thể được trừ khi thu nhập đã được hình thành.' },
      'subtract-provisions': { explanation: 'Rủi ro tín dụng đi vào lợi nhuận thông qua chi phí dự phòng, điều mà chi phí rủi ro tín dụng (Cost of Risk) mô tả.', hint: 'Các nhà phân tích so sánh lợi nhuận trước khoản này với chính khoản chi phí để tách hoạt động khỏi chu kỳ tín dụng.' },
      'tax-net-profit': { explanation: 'Lợi nhuận ròng là phần còn lại sau chi phí hoạt động, tín dụng và thuế.', hint: 'Nó được áp dụng trên phần còn lại sau các khoản khấu trừ hoạt động và tín dụng.' },
      'scale-roa-roe': { explanation: 'Chỉ có thể tính ROA và ROE khi đã biết lợi nhuận ròng, và chúng phải được đọc cùng đòn bẩy và vốn.', hint: 'Các tỷ lệ này cần con số dòng cuối cùng trước.' },
    },
  },
